def _valid_segments(path: str) -> list[str] | None:
    """Return the path segments, or None when any segment is unsafe."""
    segments = path.split("/")
    for segment in segments:
        if segment in ("", ".", ".."):
            return None
    return segments


def _count_lines(text: str) -> int:
    """Count lines terminated by \n (including \r\n); a trailing partial line counts."""
    if not text:
        return 0
    count = text.count("\n")
    if not text.endswith("\n"):
        count += 1
    return count


def handle_line_count(params: dict) -> tuple[int, dict]:
    raw = params.get("path")
    if not isinstance(raw, str) or not raw:
        return 400, {"error": "invalid path"}
    segments = _valid_segments(raw)
    if segments is None:
        return 400, {"error": "invalid path"}
    target = _DATA_DIR.joinpath(*segments)
    if not target.is_file():
        return 404, {"error": "not found"}
    text = target.read_bytes().decode("utf-8", errors="replace")
    return 200, {"lines": _count_lines(text)}
